create table public.guardians (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, name text not null, relationship text not null, phone text, email text, occupation text, address text, created_at timestamptz not null default now());
create table public.staff (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, employee_no text not null, full_name text not null, email text, phone text, designation text, active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,employee_no));
create table public.teacher_assignments (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, academic_year_id uuid not null references public.academic_years(id) on delete cascade, class_id uuid not null references public.classes(id) on delete cascade, section_id uuid references public.sections(id) on delete cascade);
alter table public.guardians enable row level security; alter table public.staff enable row level security; alter table public.teacher_assignments enable row level security;
create policy "members read guardians" on public.guardians for select using(public.is_school_member(school_id)); create policy "manage guardians" on public.guardians for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "members read staff" on public.staff for select using(public.is_school_member(school_id)); create policy "manage staff" on public.staff for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "members read assignments" on public.teacher_assignments for select using(public.is_school_member(school_id)); create policy "manage assignments" on public.teacher_assignments for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));